-- Тема 15: правки по отчёту Codex (18 исправлений в 10 вопросах), ключи не меняются.
-- Источник: scripts/questions/096_codex_topic15_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'От каких реплик каскада основной сервер получает обратную связь hot_standby_feedback, если она включена?', NULL, NULL, NULL, 'Чьи горизонты запросов учитываются на основном сервере, если hot_standby_feedback включён на всех звеньях каскада?'),
        ('question', 'Как выполняется переход на реплику при сбое мастера?', NULL, NULL, NULL, 'Как выполняется переход на реплику при сбое мастера, если внешнего кластерного ПО нет?'),
        ('question', 'Как работает фиксация при synchronous_commit = on и синхронной реплике?', NULL, NULL, NULL, 'Как работает фиксация изменяющей транзакции при synchronous_commit = on и синхронной реплике?'),
        ('option', 'Чьи горизонты запросов учитываются на основном сервере, если hot_standby_feedback включён на всех звеньях каскада?', 'От первой реплики в цепочке', 'Первой реплики без учёта нижележащих узлов', 'Обратная связь поступает от всех реплик.', 'Промежуточная реплика передаёт вверх общий горизонт с учётом нижележащих узлов.'),
        ('option', 'Чьи горизонты запросов учитываются на основном сервере, если hot_standby_feedback включён на всех звеньях каскада?', 'Ни от одной, в каскаде она не поддерживается', 'Ничьи: в каскаде обратная связь не работает', NULL, NULL),
        ('option', 'Чьи горизонты запросов учитываются на основном сервере, если hot_standby_feedback включён на всех звеньях каскада?', 'От последней реплики в цепочке', 'Последней реплики без учёта промежуточных узлов', 'Обратная связь поступает от всех реплик.', 'Промежуточные реплики тоже учитываются: каждая передаёт вверх свой горизонт вместе с горизонтами нижележащих.'),
        ('option', 'Чьи горизонты запросов учитываются на основном сервере, если hot_standby_feedback включён на всех звеньях каскада?', 'От всех реплик каскада', 'Всех реплик с передачей сведений по цепочке', 'Хотя синхронизироваться основной сервер может только с непосредственно подключённой репликой.', 'Основной сервер получает сведения от непосредственно подключённой реплики, но в них учтены горизонты всех нижележащих.'),
        ('explanation', 'Чьи горизонты запросов учитываются на основном сервере, если hot_standby_feedback включён на всех звеньях каскада?', NULL, NULL, 'При включённой обратной связи промежуточные реплики передают сведения вверх по цепочке до основного сервера.', 'Промежуточные реплики передают вверх общий горизонт, учитывающий нижележащие узлы; основной сервер получает его через непосредственно подключённую реплику.'),
        ('option', 'Что верно для каскадной репликации?', 'Обратная связь hot_standby_feedback доходит до мастера', 'Включённая обратная связь доходит до мастера', 'Да. Так основной сервер не удаляет версии строк, нужные запросам на репликах. Это не каскадная синхронная фиксация.', 'Да, если hot_standby_feedback включён на всех звеньях цепочки: тогда основной сервер не удаляет версии строк, нужные запросам на репликах. Это не каскадная синхронная фиксация.'),
        ('option', 'Что делает реплика с настроенным чтением из архива (restore_command), если очередную журнальную запись не удаётся получить по протоколу репликации?', 'Читает нужный сегмент WAL из архива', 'Пробует взять нужный сегмент из архива', NULL, NULL),
        ('option', 'Как настраивают реплику для долгих аналитических запросов?', 'Реплика откладывает записи, конфликтующие с запросами', 'Разрешают дольше откладывать применение WAL', NULL, NULL),
        ('explanation', 'Как настраивают реплику для долгих аналитических запросов?', NULL, NULL, 'Увеличение допустимой задержки применения конфликтующего WAL даёт долгому запросу закончиться ценой отставания реплики.', 'Увеличение допустимой задержки применения конфликтующего WAL даёт запросу больше времени на завершение ценой отставания реплики.'),
        ('option', 'Гарантируется ли согласованность данных, если приложение читает то с основного сервера, то с реплик?', 'Нет, даже при синхронной репликации данные могут расходиться', 'Нет, даже синхронная репликация этого не гарантирует', 'Даже при синхронной репликации можно получить устаревшие данные или такие, которых ещё не видно на основном сервере. Согласованное чтение гарантировано только при работе с одним сервером.', 'Даже при синхронной репликации можно получить устаревшие данные или такие, которых ещё не видно на основном сервере. Режим remote_apply ждёт применения на синхронных репликах, но и он не делает чтения с разных серверов единым снимком.'),
        ('option', 'Почему при wal_level = minimal физическая репликация невозможна?', 'На этом уровне нельзя создавать слоты репликации', 'Физическая репликация требует логического слота', 'Нет. Слоты при minimal действительно недоступны, но физическая репликация может работать и без слота: главная причина — недостаточный состав журнала.', 'Физическая репликация не требует логического слота и может работать вообще без слота.'),
        ('option', 'Как выполняется переход на реплику при сбое мастера, если внешнего кластерного ПО нет?', 'Вручную, если не используется внешнее кластерное ПО', 'По команде администратора на стороне реплики', NULL, NULL),
        ('option', 'Как работает фиксация изменяющей транзакции при synchronous_commit = on и синхронной реплике?', 'Фиксация ждёт, пока реплика сохранит журнал на диск', 'Фиксация ждёт записи журнала на диск реплики', NULL, NULL),
        ('option', 'Что даёт включение hot_standby_feedback?', 'Мастер не удаляет версии, нужные запросам реплики', 'Очистка не трогает версии, нужные реплике', NULL, NULL),
        ('option', 'Для чего нужна реплика с отложенным применением журнальных записей?', 'Чтобы исправить ошибку пользователя по данным прошлого', NULL, 'Реплика применяет изменения с заданной задержкой: на ней можно посмотреть данные на момент в прошлом и восстановиться после ошибки пользователя.', 'Реплика применяет изменения с заданной задержкой: пока ошибочное изменение не применено, можно остановить применение и взять данные с реплики.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
